// ── Typefaces ──────────────────────────────────────────────────────────
// Loaded second (after web.js) so every later script can read FONT_UI / FONT_NUM.
//
// Through 12.2 every string on the canvas was 'Courier New',monospace. Replaced in
// the 2026-09-16 design pass: Courier reads as a typewriter rather than a cockpit,
// its hairline serifs smear under shadowBlur, and its width is why so many labels
// needed shrink-to-fit. Design study:
// https://claude.ai/artifact/QPvLrDmGiU6przXNwXLV9y
//
//   FONT_UI  - Chakra Petch: logo, headings, labels, buttons, body text. Its clipped
//              corners echo the faceted hull (SHIP_FACETS).
//   FONT_NUM - JetBrains Mono: numbers that change or line up in columns (live score,
//              best, shards, ranks). Tabular figures, so a counting score doesn't jitter.
//
// Both ship INSIDE this file as base64 woff2, not as font files: iOS references src/
// as a folder, Android's copyGameFiles only copies src/**/*.js and the web bundle only
// concatenates scripts, so a .js file is the one thing all three builds already carry.
// No network is ever involved. Subset with fonttools (pyftsubset) to Latin, Latin-1,
// Latin Extended-A (Polish, Turkish) and General Punctuation; JetBrains Mono also keeps
// basic Cyrillic. Chakra Petch has no Cyrillic, so FONT_UI lists JetBrains Mono second
// and the canvas falls back per glyph: Russian renders in JetBrains Mono, and
// ja/ko/zh/ar/hi fall through to the system face exactly as they did under Courier.
// Total ~44 KB of woff2.
//
// Weight mapping: the canvas code only ever asks for "bold" or the default, so the
// Medium cuts are registered under weight 400. Chakra Petch's real Regular is too
// thin to survive a dark rock background at small sizes.
//
// Licences: both SIL Open Font License 1.1 (Chakra Petch (c) Cadson Demak,
// JetBrains Mono (c) JetBrains). Full text: https://openfontlicense.org
const FONT_UI  = "'Chakra Petch','JetBrains Mono',-apple-system,system-ui,'Segoe UI',Roboto,sans-serif";
const FONT_NUM = "'JetBrains Mono','Chakra Petch',-apple-system,system-ui,monospace";

// Resolves once every face is usable (or failed); main.js holds the first frame on
// it for at most FONT_WAIT_MS so the title screen never paints in a fallback face.
const FONT_WAIT_MS = 400;
const fontsReady = (function () {
    const faces = [
        ['Chakra Petch',   '400', ''],
        ['Chakra Petch',   '700', ''],
        ['JetBrains Mono', '400', ''],
        ['JetBrains Mono', '700', ''],
    ];
    if (typeof FontFace !== 'function' || !document.fonts) return Promise.resolve();
    return Promise.all(faces.map(([family, weight, data]) => {
        try {
            const bin = atob(data), buf = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
            const face = new FontFace(family, buf.buffer, { weight, style: 'normal' });
            document.fonts.add(face);
            return face.load().catch(() => {});
        } catch (e) { return Promise.resolve(); }
    }));
})();
